            "kjv": "So they sat down with him upon the ground seven days and seven nights, and none spake a word unto him: for they saw that [his] grief was very great.",
            "asv": "So they sat down with him upon the ground seven days and seven nights, and none spake a word unto him: for they saw that his grief was very great.",
            "niv": "Then they sat on the ground with him for seven days and seven nights. No one said a word to him, because they saw how great his suffering was.",
            "esv": "And they sat with him on the ground seven days and seven nights, and no one spoke a word to him, for they saw that his suffering was very great. Job Laments His Birth"
